require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('settings.manage'); $bid=current_branch_id();
$defaults=['business_name'=>'Business Name','business_phone'=>'Business Phone','business_address'=>'Business Address','business_email'=>'Business Email','tin'=>'TIN','vrn'=>'VRN','receipt_footer'=>'Receipt Footer','tax_percent'=>'Tax Percent','loyalty_spend_per_point'=>'Loyalty Spend per Point','loyalty_point_value'=>'Value of One Point','working_hours'=>'Working Hours','auto_logout_minutes'=>'Auto Logout Minutes','appointment_reminder_hours'=>'Appointment Reminder Hours','continuation_reminder_days'=>'Continuation Reminder Days','whatsapp_country_code'=>'WhatsApp Country Code','public_booking_base_url'=>'Public Booking Base URL Optional'];
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); foreach($defaults as $key=>$label){$val=trim($_POST[$key]??''); q('INSERT INTO settings(branch_id,setting_key,setting_value,setting_group,updated_by,updated_at) VALUES(?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by),updated_at=NOW()',[$bid,$key,$val, str_contains($key,'loyalty')?'loyalty':(str_contains($key,'receipt')?'receipt':'business'), $_SESSION['user_id']]);} flash('success','Business settings saved.'); redirect('modules/settings.php');}
$title='Business Settings'; $subtitle='Business name, receipt footer, tax, working hours, currency and security settings.'; include dirname(__DIR__).'/includes/header.php';?><section class="card"><form method="post"><?=csrf_field()?><div class="form-grid"><?php foreach($defaults as $key=>$label):?><div class="form-group <?=in_array($key,['business_address','receipt_footer'])?'full':''?>"><label><?=e($label)?></label><?php if(in_array($key,['business_address','receipt_footer'])):?><textarea name="<?=e($key)?>"><?=e(setting($key,'',$bid))?></textarea><?php else:?><input name="<?=e($key)?>" value="<?=e(setting($key,'',$bid))?>"><?php endif;?></div><?php endforeach;?></div><button class="btn">Save Settings</button></form></section><?php include dirname(__DIR__).'/includes/footer.php'; ?>